# Check alignment lengths, number of taxa per file, and understand file naming
for f in sorted(files):
    taxa = file_taxon_map[f]
    # Read sequences
    seqs = {}
    current = None
    with open(f) as fh:
        for line in fh:
            if line.startswith(">"):
                current = line.strip().lstrip(">")
                seqs[current] = ""
            else:
                seqs[current] += line.strip()
    aln_len = len(list(seqs.values())[0]) if seqs else 0
    print(f"{f}: {len(taxa)} taxa, aln_len={aln_len}, taxa={taxa}")
